import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/getting-started.md","filePath":"zh-CN/user-guide/getting-started.md","lastUpdated":1787586465000}'),l={name:"zh-CN/user-guide/getting-started.md"};function d(n,t,i,s,c,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>欢迎使用 Lertaro！Lertaro 是一款为 Windows 深度定制的极速文件检索与生产力启动器。本章将带你了解安装方式、核心架构、三种窗口形态以及基本的日常搜索操作。</p><h2 id="_1-下载与安装" tabindex="-1">1. 下载与安装 <a class="header-anchor" href="#_1-下载与安装" aria-label="Permalink to &quot;1. 下载与安装&quot;">​</a></h2><p>你可以在官网首页获取最新版本。每个正式发布版本均提供两种运行形式，并分别编译了 <strong>x64</strong> 与 <strong>ARM64</strong> 原生版本：</p><h3 id="安装包-lertaro-setup-exe-推荐" tabindex="-1">安装包（<code>Lertaro-Setup.exe</code>，推荐） <a class="header-anchor" href="#安装包-lertaro-setup-exe-推荐" aria-label="Permalink to &quot;安装包（`Lertaro-Setup.exe`，推荐）&quot;">​</a></h3><ul><li><strong>自动化配置</strong>：安装向导会自动注册后台索引服务（<code>Lertaro.Service</code>），配置开机自启动项，并自动检测与安装所需的 .NET 桌面运行时。</li><li><strong>平滑升级</strong>：支持静默自动检查更新与一键覆盖升级。</li></ul><h3 id="便携版-lertaro-portable-zip" tabindex="-1">便携版（<code>Lertaro-Portable.zip</code>） <a class="header-anchor" href="#便携版-lertaro-portable-zip" aria-label="Permalink to &quot;便携版（`Lertaro-Portable.zip`）&quot;">​</a></h3><ul><li><strong>解压即用</strong>：解压至任意目录即可直接运行主程序，不强制要求安装。</li><li><strong>环境补齐</strong>：若系统尚未安装对应的 .NET 桌面运行时，可直接运行解压目录自带的 <code>install-dotnet-runtime.bat</code> 脚本一键安装。</li><li><strong>数据独立与隔离</strong>：便携版默认将机器全局数据保存在程序同级目录的 <code>Data\\Machine</code>，并将各用户的私有设置保存在 <code>Data\\Users\\&lt;SID hash&gt;</code>。若该 <code>Data</code> 目录尚未创建，会自动兼容读取系统的 <code>%ProgramData%\\Lertaro</code> 和 <code>%LocalAppData%\\Lertaro</code>；一旦目录生成，便携版将优先读取本地独立数据，实现完全自包含。</li><li><strong>干净卸载与清理</strong>：当不再需要使用便携版时，在删除文件夹前请先执行自带的 <code>portable-cleanup.bat</code> 脚本。该脚本会自动停止并卸载后台服务，并清理当前用户的 <code>lertaro://</code> URI 协议及自启注册表项。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>如果你在 Windows on ARM 设备（如 Surface Pro X、高通骁龙笔记本）上运行，请优先下载 <code>Lertaro-Setup-arm64.exe</code> 或 <code>Lertaro-Portable-arm64.zip</code> 原生版本，以获得最佳性能与更低的功耗。</p></div><h2 id="_2-核心架构认知" tabindex="-1">2. 核心架构认知 <a class="header-anchor" href="#_2-核心架构认知" aria-label="Permalink to &quot;2. 核心架构认知&quot;">​</a></h2><p>首次运行 Lertaro 时，系统会安装并启动一个独立的 Windows 后台服务（<code>Lertaro.Service</code>）。理解该设计有助于你更好地掌握其工作原理：</p><ul><li><strong>前台 App（UI 与交互层）</strong>：负责渲染搜索窗口、悬浮面板、动作菜单、快捷键拦截与即时预览。前台进程始终保持极低内存占用与即时响应。</li><li><strong>后台 Service（索引与数据层）</strong>：以系统服务权限在后台运行，专门负责读取 NTFS / ReFS 的 USN 日志、监听其他文件系统的实时变动、维护网络共享索引，并建立极速内存索引树。</li><li><strong>架构优势</strong>：前台界面的重启、崩溃或更新绝不会导致后台索引丢失或重新全盘扫描；而后台的实时索引同步也绝不会阻塞前台 UI 的流畅打字体验。你可以在<a href="./settings/service-status.html"><strong>设置 → 运行状态</strong></a>中随时查看服务运行状态与索引健康度。</li></ul><h2 id="_3-三种窗口形态" tabindex="-1">3. 三种窗口形态 <a class="header-anchor" href="#_3-三种窗口形态" aria-label="Permalink to &quot;3. 三种窗口形态&quot;">​</a></h2><p>Lertaro 并非只有一个固定的搜索窗口，而是针对不同工作流设计了三种各具特色的窗口形态：</p><table tabindex="0"><thead><tr><th style="text-align:left;">窗口形态</th><th style="text-align:left;">默认唤起方式</th><th style="text-align:left;">核心特点与设计定位</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>快速窗口（Quick Window）</strong></td><td style="text-align:left;">双击 <code>Ctrl</code>（可自定义）</td><td style="text-align:left;">紧凑型屏幕居中浮窗，即输即搜，肌肉记忆友好，支持数字键快速跳转与全键盘流操作</td><td style="text-align:left;">日常高频启动应用、查找特定文件、快速计算或翻译</td></tr><tr><td style="text-align:left;"><strong>主窗口（Full Window）</strong></td><td style="text-align:left;">任务栏/开始菜单，或快捷键 <code>Ctrl+F</code></td><td style="text-align:left;">完整的大尺寸窗口，支持海量结果表格视图、侧边栏高级筛选、列排序与内置空间分析器</td><td style="text-align:left;">深度文件浏览、大范围检索、磁盘空间清理与高级筛选</td></tr><tr><td style="text-align:left;"><strong>内嵌窗口（Inline Window）</strong></td><td style="text-align:left;">打开文件对话框或资源管理器时自动嵌入</td><td style="text-align:left;">无缝内嵌到系统文件对话框或第三方管理器中，无需离开当前工作上下文</td><td style="text-align:left;">在 Office/浏览器等软件中“打开”或“另存为”文件时快速定位目标</td></tr></tbody></table><p>三种窗口形态底层共享完全相同的搜索引擎、快捷键体系、过滤规则与动作菜单。</p><h2 id="_4-首次搜索与基本交互" tabindex="-1">4. 首次搜索与基本交互 <a class="header-anchor" href="#_4-首次搜索与基本交互" aria-label="Permalink to &quot;4. 首次搜索与基本交互&quot;">​</a></h2><h3 id="即输即搜" tabindex="-1">即输即搜 <a class="header-anchor" href="#即输即搜" aria-label="Permalink to &quot;即输即搜&quot;">​</a></h3><p>打开搜索窗口后直接输入关键词即可，结果将随输入实时呈现（毫秒级响应）。搜索算法默认采用智能模糊匹配，字符无需连续输入即可跳跃命中。详细匹配规则与修饰符请参阅<a href="./search-syntax.html"><strong>搜索语法</strong></a>。</p><h3 id="结果导航与打开" tabindex="-1">结果导航与打开 <a class="header-anchor" href="#结果导航与打开" aria-label="Permalink to &quot;结果导航与打开&quot;">​</a></h3><ul><li><strong>移动光标</strong>：使用方向键 <code>↑</code> / <code>↓</code>（或配置的导航快捷键 <code>Ctrl+P</code> / <code>Ctrl+N</code>）在结果列表中上下移动选中项。</li><li><strong>直接打开</strong>：按下 <code>Enter</code> 立即使用默认程序打开选中的文件或启动应用程序。</li><li><strong>定位目录</strong>：按下 <code>Ctrl+Enter</code> 可在文件资源管理器中直接定位并选中该文件。</li><li><strong>管理员身份运行</strong>：按下 <code>Ctrl+Shift+Enter</code> 以管理员权限运行程序。</li><li><strong>数字直达</strong>：在快速窗口中，可直接按下 <code>Ctrl</code> + <code>1</code>–<code>9</code> 直接打开前 9 项结果。</li></ul><h3 id="动作菜单与扩展操作" tabindex="-1">动作菜单与扩展操作 <a class="header-anchor" href="#动作菜单与扩展操作" aria-label="Permalink to &quot;动作菜单与扩展操作&quot;">​</a></h3><p>按下 <code>Ctrl+O</code> 或在选中项上按方向键 <code>→</code>，即可展开功能强大的<strong>动作菜单</strong>，执行复制路径、属性查看、文件增删剪贴或调用插件扩展动作。更多操作技巧请阅读<a href="./actions-and-preview.html"><strong>动作菜单与预览</strong></a>与<a href="./hotkeys.html"><strong>热键</strong></a>。</p>',23)])])}const p=e(l,[["render",d]]);export{u as __pageData,p as default};
